file_lines = [
    '"""Deep district-level expansion for Sindh (75+ Landmarks)."""',
    'from __future__ import annotations',
    'from scripts.landmark_builder.generator import make_clean_record',
    '',
    'SINDH_DEEP_DATA = ['
]

for t in data_tuples:
    file_lines.append(f'    {repr(t)},')

file_lines.extend([
    ']',
    '',
    'def get_sindh_deep() -> list[dict]:',
    '    records = []',
    '    for item in SINDH_DEEP_DATA:',
    '        records.append(make_clean_record(',
    '            slug=item[0], name=item[1], name_ur=item[2], category=item[3], city=item[4], region="Sindh",',
    '            lat=item[5], lon=item[6], radius=item[7], short_en=item[8], short_ur=item[9], desc_en=item[10], desc_ur=item[11]',
    '        ))',
    '    return records',
    ''
])

with open(dest, 'w', encoding='utf-8') as f:
    f.write('\n'.join(file_lines))

print(f'Successfully wrote {len(data_tuples)} landmarks to {dest}!')
